<#
.SYNOPSIS
    Self-extracting bundle for the WorkflowEngine.ConsoleDbFirst solution.

.DESCRIPTION
    Running this script recreates the full console-dbfirst-clean directory
    tree from base64-encoded file payloads embedded directly in this script,
    then optionally builds the solution with `dotnet build`.

    Prerequisites (Windows):
        - .NET 10 SDK  (https://dotnet.microsoft.com/download)
        - SQL Server 2019+ / LocalDB / Azure SQL (connection string below)

.PARAMETER OutputPath
    Root folder to extract into.  Defaults to .\console-dbfirst-clean

.PARAMETER ConnectionString
    Optional SQL Server connection string injected into appsettings.json.
    If omitted the shipped appsettings.Development.json values are used.

.PARAMETER NoBuild
    Skip the `dotnet build` step after extraction.

.PARAMETER NoTest
    Skip the `dotnet test` step after build.

.EXAMPLE
    .\Restore-WorkflowEngine.ps1
    .\Restore-WorkflowEngine.ps1 -OutputPath C:\Projects\workflow
    .\Restore-WorkflowEngine.ps1 -ConnectionString "Server=.;Database=WfEngine;Integrated Security=true;Encrypt=false"
    .\Restore-WorkflowEngine.ps1 -NoBuild
#>
[CmdletBinding()]
param(
    [string] $OutputPath        = ".\console-dbfirst-clean",
    [string] $ConnectionString  = "",
    [switch] $NoBuild,
    [switch] $NoTest
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

# ── Helpers ──────────────────────────────────────────────────────────────────
function Write-Step([string]$msg) {
    Write-Host ""
    Write-Host "  >> $msg" -ForegroundColor Cyan
}

function Write-Ok([string]$msg) {
    Write-Host "     $msg" -ForegroundColor Green
}

function Expand-File([string]$relPath, [string]$b64) {
    $target = Join-Path $OutputPath $relPath
    $dir    = Split-Path $target -Parent
    if (-not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($target, $bytes)
}

# ── Banner ────────────────────────────────────────────────────────────────────
Write-Host ""
Write-Host "  WorkflowEngine Console DB-First — Self-Extracting Bundle" -ForegroundColor Yellow
Write-Host "  Generated : 2026-05-13 12:08 UTC"
Write-Host "  Target    : $OutputPath"
Write-Host ""

