# ── Optional: patch connection string ─────────────────────────────────────────
if ($ConnectionString -ne "") {
    Write-Step "Patching appsettings.json with supplied connection string..."
    $settingsPath = Join-Path $OutputPath "src\WorkflowEngine.Console\appsettings.json"
    if (Test-Path $settingsPath) {
        $json = Get-Content $settingsPath -Raw | ConvertFrom-Json
        if ($null -eq $json.ConnectionStrings) {
            $json | Add-Member -NotePropertyName ConnectionStrings -NotePropertyValue ([PSCustomObject]@{})
        }
        $json.ConnectionStrings | Add-Member -NotePropertyName DefaultConnection `
            -NotePropertyValue $ConnectionString -Force
        $json | ConvertTo-Json -Depth 10 | Set-Content $settingsPath -Encoding UTF8
        Write-Ok "appsettings.json updated."
    } else {
        Write-Warning "appsettings.json not found — skipping connection string patch."
    }
}

# ── Build ─────────────────────────────────────────────────────────────────────
if (-not $NoBuild) {
    Write-Step "Building solution (dotnet build)..."

    # Prefer .slnx if dotnet supports it; fall back to .sln
    $slnx = Join-Path $OutputPath "WorkflowEngine.ConsoleDbFirst.slnx"
    $sln  = Join-Path $OutputPath "src\WorkflowEngine.sln"

    if (Test-Path $slnx) {
        $slnFile = $slnx
    } elseif (Test-Path $sln) {
        $slnFile = $sln
    } else {
        Write-Warning "No solution file found; running dotnet build on src\ directory."
        $slnFile = Join-Path $OutputPath "src"
    }

    Write-Host "     Solution : $slnFile" -ForegroundColor DarkGray
    & dotnet build $slnFile --configuration Release /nologo
    if ($LASTEXITCODE -ne 0) {
        Write-Host ""
        Write-Host "  BUILD FAILED (exit $LASTEXITCODE)" -ForegroundColor Red
        exit $LASTEXITCODE
    }
    Write-Ok "Build succeeded."
} else {
    Write-Host "  (Build skipped via -NoBuild)" -ForegroundColor DarkGray
}

# ── Test ──────────────────────────────────────────────────────────────────────
if (-not $NoBuild -and -not $NoTest) {
    Write-Step "Running tests (dotnet test)..."
    $testProj = Join-Path $OutputPath "tests\WorkflowEngine.Tests\WorkflowEngine.Tests.csproj"
    if (Test-Path $testProj) {
        Write-Host "     Project : $testProj" -ForegroundColor DarkGray
        Write-Host "     NOTE    : Integration tests require SQL Server — unit-only tests will still pass." -ForegroundColor DarkGray
        & dotnet test $testProj --configuration Release /nologo --no-build `
            --logger "console;verbosity=minimal"
        if ($LASTEXITCODE -ne 0) {
            Write-Host ""
            Write-Host "  SOME TESTS FAILED (exit $LASTEXITCODE)" -ForegroundColor Yellow
            Write-Host "  If you see SQL connection errors, supply -ConnectionString or set up LocalDB." -ForegroundColor Yellow
        } else {
            Write-Ok "All tests passed."
        }
    } else {
        Write-Host "  (Test project not found — skipping)" -ForegroundColor DarkGray
    }
} elseif ($NoTest) {
    Write-Host "  (Tests skipped via -NoTest)" -ForegroundColor DarkGray
}

# ── Done ──────────────────────────────────────────────────────────────────────
Write-Host ""
Write-Host "  Extraction complete." -ForegroundColor Green
Write-Host ""
Write-Host "  Next steps:" -ForegroundColor Yellow
Write-Host "    1. Edit  $OutputPath\src\WorkflowEngine.Console\appsettings.json"
Write-Host "       and set your SQL Server connection string."
Write-Host "    2. Run   dotnet run --project src\WorkflowEngine.Console -- init-db"
Write-Host "    3. Run   dotnet run --project src\WorkflowEngine.Console -- verify-seed"
Write-Host "    4. Run   dotnet run --project src\WorkflowEngine.Console -- demo"
Write-Host ""
